def bus_timer(current_time: str) -> int:
    hh, mm = map(int, current_time.split(':'))
    total_minutes = hh * 60 + mm
    bus_times = [6 * 60 + 15 * i for i in range(10)]
    bus_times.append(24 * 60)
    for bt in bus_times:
        if total_minutes + 5 <= bt:
            return bt - total_minutes - 5
    return 55
